from ..utils import intlify
from ..commons import TRACE_STORE


TARGET_PATH = '/home/ute/'
DEFAULT_ALIAS = 'default'


class TracesPublicInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def collect_machs_tti_trace(self, cell_id, trace_time, output_path=TARGET_PATH, trace_alias=DEFAULT_ALIAS):
        """
        Collect MacHS TTI Traces and save them to a file.

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 1.1.0

        **Input parameters:**

        +----------------+------+----------------------------------------------------------------+
        | Parameter name | Man. | Description                                                    |
        +================+======+================================================================+
        | cell_id        | Yes  | WCDMA cell id                                                  |
        +----------------+------+----------------------------------------------------------------+
        | trace_time     | Yes  | collection time in seconds or as a valid Robot's time string   |
        +----------------+------+----------------------------------------------------------------+
        | output_path    | No   | a path where TXT or ZIP file with traces will be saved         |
        +----------------+------+----------------------------------------------------------------+
        | trace_alias    | No   | an alias for trace collector                                   |
        +----------------+------+----------------------------------------------------------------+

        **Examples:**

        .. code-block:: robotframework

            Collect MacHS TTI Trace    cell_id=29101    trace_time=60
            Collect Machs TTI Trace    cell_id=29101    trace_time=2 minutes    output_path=/tmp
        """
        trace_time = timestr_to_secs(trace_time)
        cell_id = int(cell_id)
        _collect_machs_tti_trace(cell_id, trace_time, output_path, trace_alias, self.connection)

    def collect_rake_trace(self, trace_time, output_path=TARGET_PATH, trace_alias=DEFAULT_ALIAS,
                           rake_trace_mask=1984, rake_trace_user_id=0):
        """
        Collect Rake Traces and save them to a file.

        .. note::
            Before collecting traces, it also attempts to set Rake Trace config parameters: rake_trace_mask and rake_trace_user_id

        **Input parameters:**

        +-----------------------+------+----------------------------------------------------------------+
        | Parameter name        | Man. | Description                                                    |
        +=======================+======+================================================================+
        | trace_time            | Yes  | collection time in seconds or as a valid Robot's time string   |
        +-----------------------+------+----------------------------------------------------------------+
        | output_path           | No   | a path where output file with traces will be saved             |
        +-----------------------+------+----------------------------------------------------------------+
        | trace_alias           | No   | an alias for trace collector                                   |
        +-----------------------+------+----------------------------------------------------------------+
        | rake_trace_mask       | No   | RAD parameter for Rake Trace; default value is 1984            |
        +-----------------------+------+----------------------------------------------------------------+
        | rake_trace_user_id    | No   | RAD parameter for Rake Trace; default value is 0               |
        +-----------------------+------+----------------------------------------------------------------+

        **Example:**

        .. code-block:: robotframework

            Collect Rake Trace    trace_time=60
            Collect Rake Trace    trace_time=2 minutes    output_path=/tmp
            Collect Rake Trace    trace_time=10 seconds   rake_trace_mask=8190

        """
        rake_trace_mask, rake_trace_user_id = intlify(rake_trace_mask, rake_trace_user_id)
        ConfigurableRadParamsInterface(self.connection).set_rake_config_params(rake_trace_mask, rake_trace_user_id)

        trace_time = timestr_to_secs(trace_time)
        _collect_rake_trace(trace_time, output_path, trace_alias, self.connection)

